      normalized == '[::1]' ||
      normalized == '10.0.2.2';
}

String _sanitizeManualServerAddress(String raw) {
  final endpoint = parseServerEndpoint(raw);
  if (endpoint == null || _shouldSkipDiscoveryHost(endpoint.host)) {
    return _defaultWifiServerAddress;
  }
  return endpoint.baseUrl;
}
